        v.x = fast_mish_opt(v.x);
        v.y = fast_mish_opt(v.y);
        v.z = fast_mish_opt(v.z);
        v.w = fast_mish_opt(v.w);
        reinterpret_cast<float4*>(output)[i] = v;
    }

    // Handle remainder
